{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C224","C239","C251","C256","C235","C270","C272","C231","C241","C258","C248","C229","C233","C271","C267","C242"],
  "contradictory_card_ids": ["C252","C262"],
  "prediction_basis_card_ids": ["C224","C239","C251","C235","C270","C272"],
  "claims": [
    {
      "claim": "L6 hepatic stability records for the most structurally relevant methylsulfonylphenyl analog vismodegib show high metabolic stability in human hepatocytes with 96 ± 12% remaining after 3 h and stability across mouse, rat, dog and human hepatocytes, indicating low hepatic presystemic loss.",
      "card_ids": ["C224","C239","C251","C256"]
    },
    {
      "claim": "Methylsulfonylphenyl and sulfonyl-amide chloropyridine analogs show low to moderate human liver microsomal intrinsic clearance, for example 22.9 µL/min for compound 10b and 14 to 47 µL/min/mg across the chloropyridine sulfonyl-amide series, which does not support F below 20%.",
      "card_ids": ["C235","C270","C272","C231","C241","C258","C248","C229","C233","C271"]
    },
    {
      "claim": "Celecoxib, a methylphenyl sulfonamide comparator, shows moderate HLM CLint of 22.6 to 29.8 µL/min/mg, consistent with the supportive hepatic stability direction.",
      "card_ids": ["C267","C242"]
    },
    {
      "claim": "Two methylsulfonylphenyl indazole analogs show high HLM intrinsic clearance of 442.7 and 793.4 mL/min/kg, but their basic indazole-amine scaffold and different ionization reduce transferability to the neutral query.",
      "card_ids": ["C252","C262"]
    },
    {
      "claim": "No query-specific absolute F or matched oral/IV exposure measurement exists; the high prediction remains based on transferable L1/L2 contexts plus absorption, permeability, efflux and now hepatic stability support.",
      "card_ids": ["C224","C235"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C224","C239","C251","C256","C235","C270","C272","C231","C241","C258","C248","C229","C233","C271","C267","C242","C252","C262"]
    }
  ],
  "evidence_gaps": [
    "No query-specific absolute oral bioavailability or matched oral/IV exposure measurement is available.",
    "No query-specific hepatic clearance or metabolic stability measurement exists; L6 support is analog-based.",
    "High logD 4.18 may limit solubility but no dose-solubility relationship is available.",
    "High-clearance indazole analogs are less transferable, leaving residual uncertainty about scaffold effects.",
    "Transfer likelihood is a relevance signal, not an experimental result."
  ],
  "decision_summary": "L6 hepatic clearance and metabolic stability evidence is directionally supportive. The most relevant methylsulfonylphenyl analog vismodegib is highly stable in human hepatocytes with 96 ± 12% remaining, and the chloropyridine sulfonyl-amide series shows low to moderate HLM CLint of 14 to 47 µL/min/mg, indicating limited hepatic presystemic loss. High-clearance methylsulfonylphenyl indazole analogs are less transferable due to scaffold and ionization differences. Combined with prior L1/L2 direct F contexts of 20% or higher and L4/L5 absorption and efflux support, the high prediction is retained and strengthened with moderate confidence."
}

